def validate_lag_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LAG_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm/lags 与 lag 契约一致，
    # 复用其全量校验
    bridges, links, delay, bridge, ports, age, storm, lags = (
        validate_lag_config({key: config[key] for key in LAG_CONFIG_KEYS})
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, storm, lags, max_frame


